import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', sub:'Tuff dag',     variant:'ember' },
  { score:2, emoji:'😟', label:'Dåligt',         sub:'Lite tungt',   variant:'dusk'  },
  { score:3, emoji:'😐', label:'Okej',           sub:'Varken eller', variant:'dark'  },
  { score:4, emoji:'🙂', label:'Bra',            sub:'Ganska bra',   variant:'moss'  },
  { score:5, emoji:'😄', label:'Väldigt bra',    sub:'Riktigt bra!', variant:'slate' },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick');

  const activeIdx = hovered ?? selected ?? 2;
  const activeMood = MOODS[activeIdx];

  const handlePick = (idx) => { setSelected(idx); setTimeout(()=>setStep('note'), 280); };

  const handleSave = () => {
    const m = MOODS[selected];
    addMood(m.score, m.emoji, m.label, note);
    setStep('done');
  };

  if (todayChecked && step !== 'done') return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <Orb3D size={200} variant="slate" speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(24px,5vw,36px)', fontWeight:700, letterSpacing:'-0.03em', color:'#1a1a1e', marginBottom:12 }}>Redan incheckad idag</h2>
        <p style={{ fontSize:14, color:'rgba(26,26,30,0.45)', marginBottom:32, fontWeight:300 }}>Kom tillbaka imorgon.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'#1a1a1e', color:'#fff', fontSize:13, fontWeight:600 }}>Se historik</button>
          <button onClick={()=>setPage('home')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(26,26,30,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <Orb3D size={220} variant={MOODS[selected].variant} speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#1a1a1e', marginBottom:12 }}>Sparat</h2>
        <p style={{ fontSize:14, color:'rgba(26,26,30,0.45)', marginBottom:36, fontWeight:300 }}>Bra att du checkade in.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'#1a1a1e', color:'#fff', fontSize:13, fontWeight:600 }}>Se historik</button>
          <button onClick={()=>setPage('home')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(26,26,30,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 28px 60px', maxWidth:420, width:'100%', animation:'fadeUp .5s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <Orb3D size={200} variant={MOODS[selected].variant} speed={0.25} />
        </div>
        <div style={{ textAlign:'center', marginBottom:32 }}>
          <span style={{ fontSize:28, display:'block', marginBottom:8 }}>{MOODS[selected].emoji}</span>
          <h2 style={{ fontSize:28, fontWeight:700, letterSpacing:'-0.03em', color:'#1a1a1e' }}>{MOODS[selected].label}</h2>
          <p style={{ fontSize:13, color:'rgba(26,26,30,0.4)', marginTop:4, fontWeight:300 }}>{MOODS[selected].sub}</p>
        </div>
        <div className="glass" style={{ borderRadius:18, padding:'18px', marginBottom:14 }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(26,26,30,0.35)', marginBottom:10 }}>Valfri notering</p>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag?"
            style={{ width:'100%', background:'transparent', border:'none', color:'#1a1a1e', fontSize:14, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7 }} />
        </div>
        <button onClick={handleSave} style={{ width:'100%', padding:'14px', borderRadius:100, background:'#1a1a1e', color:'#fff', fontSize:14, fontWeight:600, marginBottom:10 }}>Spara</button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'8px', fontSize:13, color:'rgba(26,26,30,0.35)' }}>← Ändra humör</button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="default" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 28px 52px', maxWidth:480, margin:'0 auto', display:'flex', flexDirection:'column', alignItems:'center' }}>

        {/* Orb — centered, changes with hover */}
        <div style={{ marginBottom:36, animation:'fadeIn .6s ease both', transition:'all .5s ease' }}>
          <Orb3D size={280} variant={activeMood.variant} speed={0.3} />
        </div>

        {/* Heading */}
        <div style={{ width:'100%', marginBottom:28, animation:'fadeUp .7s .1s cubic-bezier(0.16,1,0.3,1) both' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(26,26,30,0.35)', marginBottom:10 }}>Daglig check-in</p>
          <h1 style={{ fontSize:'clamp(32px,7vw,52px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#1a1a1e', marginBottom:8 }}>
            HUR MÅR<br/>
            <span style={{ color:'rgba(26,26,30,0.2)' }}>DU IDAG?</span>
          </h1>
        </div>

        {/* Mood list — clean rows, no boxes */}
        <div style={{ width:'100%', display:'flex', flexDirection:'column', gap:4, animation:'fadeUp .7s .15s cubic-bezier(0.16,1,0.3,1) both' }}>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isHov = hovered === idx;
            const isSel = selected === idx;
            return (
              <button key={m.score}
                onMouseEnter={()=>setHovered(idx)}
                onMouseLeave={()=>setHovered(null)}
                onClick={()=>handlePick(idx)}
                style={{
                  display:'flex', alignItems:'center', justifyContent:'space-between',
                  padding:'14px 18px', borderRadius:14,
                  background: isHov||isSel ? 'rgba(255,255,255,0.55)' : 'rgba(255,255,255,0.25)',
                  border:`1px solid ${isHov||isSel ? 'rgba(0,0,0,0.1)' : 'rgba(0,0,0,0.05)'}`,
                  backdropFilter:'blur(16px)',
                  transform: isHov ? 'translateX(5px)' : 'none',
                  transition:'all .2s cubic-bezier(0.16,1,0.3,1)',
                }}>
                <div style={{ display:'flex', alignItems:'center', gap:12 }}>
                  <span style={{ fontSize:22, transition:'transform .2s', transform: isHov ? 'scale(1.15)' : 'scale(1)' }}>{m.emoji}</span>
                  <div style={{ textAlign:'left' }}>
                    <div style={{ fontSize:14, fontWeight:600, color:'#1a1a1e', letterSpacing:'-0.01em' }}>{m.label}</div>
                    <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(26,26,30,0.35)', letterSpacing:'0.06em', marginTop:1 }}>{m.sub}</div>
                  </div>
                </div>
                <span style={{ fontSize:11, color:'rgba(26,26,30,0.25)', opacity: isHov ? 1 : 0, transition:'opacity .2s' }}>→</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}
